$string['settingdebugmode'] = 'Debug mode';
$string['settingdebugmode_desc'] = 'When enabled, writes a PHP debug file log (separate from API traffic / diagnostics stored in the database) to a fixed path under the Moodle data directory. Keep disabled in production.';
$string['settingdefaultdifficultymode'] = 'Default difficulty mode';
$string['settingdiagnosticretentiondays'] = 'Diagnostic payload retention (days)';
$string['settingdiagnosticretentiondays_desc'] = 'How many days the FULL diagnostic payload - the system prompt, the response schema and the raw provider response - is kept on a log entry. Default 30. After this the payload is removed by a daily task, and the log entry itself and all of its technical fields (provider, HTTP status, token counts, request id, result) are kept permanently. A GDPR deletion request removes the payload immediately, regardless of this setting. The value cannot be 0 and there is no unlimited option: this data stops being useful long before it stops being sensitive.';
$string['settingdraftcourseid'] = 'Draft course ID';
$string['settingdraftcourseid_desc'] = 'The numeric course ID whose context AI-generated draft questions are created in until approved. Use a dedicated, hidden course with no students enrolled - draft categories are no longer created at the site-wide system context, so this course\'s own context is what actually keeps unreviewed AI content away from ordinary question bank browsing. New generations are blocked until this is set to a course that exists.';
$string['settingenabled'] = 'Enable plugin';
$string['settingenabled_desc'] = 'When disabled, no ArtQTML pages are accessible and the "New generation" button is hidden.';
$string['settingexplanationdefault'] = 'Explain each answer option by default';
$string['settingexplanationdefault_desc'] = 'Default value of the per-generation "explain each answer option" toggle. Off by default: the explanation is written per option, so the cost grows with the number of options rather than the number of questions. Only applies to True/False, Single choice and Multiple choice.';
$string['settingfeedbackcorrect'] = 'Feedback template (correct answer)';
$string['settingfeedbackincorrect'] = 'Feedback template (incorrect answer)';
$string['settingfeedbackpartial'] = 'Feedback template (partially correct answer)';
$string['settingfefmaxoptions'] = 'FE/FT maximum answer options';
$string['settingfefmaxoptions_desc'] = 'Maximum number of answer options the AI must generate for single/multiple choice questions. Must be at least the configured minimum.';
$string['settingfefminoptions'] = 'FE/FT minimum answer options';
$string['settingfefminoptions_desc'] = 'Minimum number of answer options the AI must generate for single/multiple choice questions.';
$string['settinggeneratorcontextwindow'] = 'Generator context window (tokens)';
$string['settinggeneratorcontextwindow_desc'] = 'Used for the generator max_tokens value and token estimation.';
$string['settinggeneratorprompttemplate'] = 'Generator prompt template';
$string['settinggeneratorprompttemplate_desc'] = 'The complete system prompt sent to Claude. Placeholders: {{QUESTION_COUNTS}}, {{DIFFICULTY_MODE}}, {{KNOWLEDGE_SOURCE}}, {{NEGATION_INSTRUCTION}}, {{TYPE_INSTRUCTIONS}}. The source text has no placeholder - it is sent as a separate user message. <strong>Deleting a placeholder means the value behind it never reaches the model.</strong>';
$string['settinggeneratortokenbudget'] = 'Generator monthly token budget';
$string['settinggeneratortokenbudget_desc'] = '0 = unlimited. New generations are blocked once this many Claude tokens have been used this cycle.';
$string['settinginstructiondefault'] = 'Default AI instruction';
$string['settinginstructiondefault_desc'] = 'Prefilled default for this type\'s per-generation AI instruction field; still applies to the prompt even if the field is hidden (see "Show standard instruction field" below).';
$string['settingmaxfilesize'] = 'Max upload file size (bytes)';
$string['settingmaxfilesize_desc'] = 'Maximum size for uploaded source files on the text upload page. Cannot exceed the Moodle site upload limit.';
$string['settingmaxquestionsperrun'] = 'Max questions per generation';
$string['settingmaxquestionsperrun_desc'] = 'The most questions a user may request in a single generation.';
$string['settingmaxsourcetokens'] = 'Maximum source-text size';
$string['settingmaxsourcetokens_desc'] = 'Maximum estimated number of tokens allowed in pasted or uploaded source text. The estimate uses approximately four Unicode characters per token, which is what the counter on the upload page shows - it is not the provider\'s own tokenizer. Set to 0 to use 80% of the configured generator context window, leaving room for the system prompt, the response schema and the model\'s answer. Text over the limit is rejected rather than truncated, so nobody gets questions about a document they did not upload. This setting is independent of the monthly token budget.';
$string['settingnegationhighlightdefault'] = 'Highlight negation words by default';
$string['settingnegationhighlightdefault_desc'] = 'Default value of the per-generation "highlight negation words" toggle; users can override it per generation.';
$string['settingorderinggradingtype'] = 'Ordering (SR) default grading type';
$string['settingorderinggradingtype_desc'] = 'qtype_ordering gradingtype constant used as the default for generated ordering questions.';
$string['settingorderingnumberingtype'] = 'Ordering (SR) default numbering style';
$string['settingorderingnumberingtype_desc'] = 'qtype_ordering numberingstyle constant used as the default for generated ordering questions.';
$string['settingpromptdifficultybloom'] = 'Difficulty levels - Bloom mode';
$string['settingpromptdifficultybloom_desc'] = 'Replaces {{DIFFICULTY_MODE}} when the generation uses Bloom mode. {{REMEMBER}}, {{UNDERSTAND}} and {{APPLY}} take the requested counts. This is where the levels are defined - without a definition the model receives only the labels and invents its own scale.';
$string['settingpromptdifficultyfreetextreference'] = 'Difficulty - free-text reference';
$string['settingpromptdifficultyfreetextreference_desc'] = 'Replaces {{DIFFICULTY_MODE}} when the teacher describes the difficulty in their own words. This fragment is trusted system-prompt text: the teacher\'s actual description is NOT substituted into it. It only tells the model where that description is - in the structured user message, under teacher_preferences.difficulty - and that it is a preference rather than an instruction. Emptying this field removes the explanation; it does not put the teacher\'s text back into the system prompt.';
$string['settingpromptdifficultyscale'] = 'Difficulty levels - Easy / Medium / Hard mode';
$string['settingpromptdifficultyscale_desc'] = 'Replaces {{DIFFICULTY_MODE}} when the generation uses the Easy/Medium/Hard scale. {{EASY}}, {{MEDIUM}} and {{HARD}} take the requested counts. This is where the levels are defined - without a definition the model receives only the labels and invents its own scale.';
$string['settingpromptfeedbackcorrect'] = 'Feedback style - correct answer';
$string['settingpromptfeedbackcorrect_desc'] = 'Added to {{TYPE_INSTRUCTIONS}} for each question type whose feedback template is filled in. {{TYPE}} is the type code, {{FEEDBACK}} the configured template.';
$string['settingpromptfeedbackincorrect'] = 'Feedback style - incorrect answer';
$string['settingpromptfeedbackincorrect_desc'] = 'As above, for the incorrect-answer case.';
$string['settingpromptinjectionpatterns'] = 'Prompt injection patterns';
$string['settingpromptinjectionpatterns_desc'] = 'Additional site-specific prompt-injection phrases, separated by commas or new lines. Mandatory built-in patterns always remain active, so leaving this field empty does not switch screening off. Phrases shorter than four characters are ignored: they would match practically every document and refuse every upload. This is heuristic screening only; system-message isolation, structured output and human review remain required.';
$string['settingpromptitemcount'] = 'SR item count';
$string['settingpromptitemcount_desc'] = 'Added to {{TYPE_INSTRUCTIONS}} when the generation contains SR questions. {{SR_ITEM_COUNT}} takes the generation-level value if given, otherwise the site setting.';
$string['settingpromptjsoninvalid'] = 'Invalid JSON - retry notice';
$string['settingpromptjsoninvalid_desc'] = 'Appended to the system prompt on a retry, after the model returned a response that could not be parsed. The base template says nothing about the schema, because the request already carries it.';
$string['settingpromptknowledgeownknowledge'] = 'Knowledge source - own knowledge allowed';
$string['settingpromptknowledgeownknowledge_desc'] = 'Replaces {{KNOWLEDGE_SOURCE}} when the teacher allowed the model to add its own knowledge.';
$string['settingpromptknowledgesourceonly'] = 'Knowledge source - source text only';
$string['settingpromptknowledgesourceonly_desc'] = 'Replaces {{KNOWLEDGE_SOURCE}} when the teacher chose to use only the uploaded text.';
$string['settingpromptnegation'] = 'Negation highlighting';
$string['settingpromptnegation_desc'] = 'Replaces {{NEGATION_INSTRUCTION}} when the teacher switched negation highlighting on. Otherwise that placeholder is empty.';
$string['settingpromptnosourcemetaref'] = 'No source-document meta-reference in stems';
$string['settingpromptnosourcemetaref_desc'] = 'Always added to {{TYPE_INSTRUCTIONS}}. Tells the model not to write phrases such as "szöveg szerint", "according to the text", or "based on the passage" in the question stem or answer options. The server also strips a leading clause and rejects leftovers; this fragment is the prompt half of that rule.';
$string['settingpromptoptioncount'] = 'Answer option count';
$string['settingpromptoptioncount_desc'] = 'Added to {{TYPE_INSTRUCTIONS}} when the generation contains FE or FT questions. Its own placeholders {{OPTION_MIN}} and {{OPTION_MAX}} take the values of the corresponding settings.';
$string['settingpromptoptionexplanation'] = 'Prompt - per-option explanation';
$string['settingpromptoptionexplanation_desc'] = 'Added to the system prompt for each type where the teacher asked for per-option explanations. Reaches the model only when the switch is on, in step with the response schema - the two must agree, or the call asks for something the response cannot carry.';
$string['settingpromptoptionexplanationtruefalse'] = 'Prompt - per-option explanation, True/False';
$string['settingpromptoptionexplanationtruefalse_desc'] = 'Added after the setting above, and only for True/False questions. A True/False question has two options and a single claim, so an explanation for each of them plus the general feedback states the same fact three times - measured on 2026-08-02. This clause asks for the misreading a student who chose that option most likely made, instead of for the fact.';
$string['settingpromptshortanswer'] = 'Prompt - short answer, one word';
$string['settingpromptshortanswer_desc'] = 'Added to the prompt whenever the generation contains short answer questions. Moodle compares what the student types against one stored string, so the accepted answer has to be a single word - and that constrains the question, not only the answer. Measured on 2026-08-02: without this, only 10 of 36 generated short answers were a word a student could type; the other 26 were full sentences nobody could get right.';
$string['settingpromptteacherinstructionreference'] = 'Per-type instruction - teacher override reference';
$string['settingpromptteacherinstructionreference_desc'] = 'Added to {{TYPE_INSTRUCTIONS}} for each question type where the teacher replaced the admin default with their own instruction. This fragment is trusted system-prompt text: the teacher\'s instruction is NOT substituted into it, only referenced - it travels in the structured user message under teacher_preferences.type_instructions. {{TYPE}} is replaced by the server with a supported question type code and nothing else. Where the teacher did not override anything, the admin default for that type is used as before. This is one layer of a defence in depth; it is not a guarantee against prompt injection.';
$string['settingretrydefault'] = 'Allow multiple attempts by default';
$string['settingretrydefault_desc'] = 'Default value of the per-generation "allow multiple attempts" toggle for each type that supports it; users can override it per generation. Never applies to True/False (IH).';
$string['settingshowstandardinstruction'] = 'Show the AI instruction field to teachers';
$string['settingshowstandardinstruction_desc'] = 'When on, teachers can edit the per-type AI instruction on the question settings page. What they type reaches the model as the teacher\'s own request rather than as a system instruction - so it shapes the generated questions, but it cannot override the rules an administrator has set. When off, the field is hidden and every generation runs with the default instruction above. The default instruction applies either way.';
$string['settingsqlkeywords'] = 'SQL injection keywords';
$string['settingsqlkeywords_desc'] = 'Comma-separated SQL keywords screened for, together with the Moodle table prefix, in uploaded source text.';
$string['settingsritemcount'] = 'Ordering (SR) item count';
$string['settingsritemcount_desc'] = 'The number of items the AI generates for each ordering question. Ordering questions are sensitive to this number: every question needs that many distinct items that the source text genuinely places in a sequence - a process, a chronology, a ranking or a list. A short source text offers only a few such sequences, so a higher number here produces fewer ordering questions rather than longer ones. Can be overridden per generation.';
$string['settingtestconnection'] = 'Connection test';
$string['settingtokenbudgetwarningpct'] = 'Warning threshold (%)';
$string['settingtokenbudgetwarningpct_desc'] = 'Show a warning once usage reaches this percentage of the monthly budget.';
$string['settingtokencyclestartday'] = 'Cycle start day of month';
$string['settingtokencyclestartday_desc'] = 'Day of the month (1-28) the token usage counters reset.';
$string['settingtokenusage'] = 'Current usage';
$string['settingvalidationpromptcategory'] = 'Problem category instruction';
$string['settingvalidationpromptcategory_desc'] = 'Replaces {{CATEGORY_INSTRUCTION}}. {{PROBLEM_CATEGORIES}} is filled from the schema\'s own value list.';
$string['settingvalidationpromptdifficulty'] = 'Difficulty level check';
$string['settingvalidationpromptdifficulty_desc'] = 'Replaces {{DIFFICULTY_INSTRUCTION}} in the validator prompt. Asks the validator to judge whether a question really demands the operation its difficulty label stands for. {{DIFFICULTY_DEFINITIONS}} is filled with the same level definitions the generator was given for that generation, so the two sides measure against one scale. Left out entirely in free-text difficulty mode, where there are no levels to check against.';
$string['settingvalidationpromptitemsource'] = 'Ordering item source check';
$string['settingvalidationpromptitemsource_desc'] = 'Replaces {{ITEMSOURCE_INSTRUCTION}} in the validator prompt. Asks the validator to check that every item of an ordering question is named by the source text. The generator is told to produce a fixed number of items and will invent one when the text cannot supply that many (BL-31); this is where that is caught, because an ordering question has no distractors - the student must place every item.';
$string['settingvalidationpromptlanguage'] = 'Justification language';
$string['settingvalidationpromptlanguage_desc'] = 'Replaces {{LANGUAGE_INSTRUCTION}}. Val-030: the justification follows the language of the source text, like the questions themselves.';
$string['settingvalidationpromptshortanswer'] = 'Short answer - one word check';
$string['settingvalidationpromptshortanswer_desc'] = 'Replaces {{SHORTANSWER_INSTRUCTION}} in the validator prompt. Asks the validator to check that a short answer question stores a single word. Moodle compares what the student types against that one string, so a sentence answer is a question they can know and still score zero on. Measured on 2026-08-02: 26 of 36 generated short answers were sentences, and the validator raised none of them, because it had no rule to raise them under.';
$string['settingvalidationpromptsuggestion'] = 'Suggestion field instruction';
$string['settingvalidationpromptsuggestion_desc'] = 'Replaces {{SUGGESTION_INSTRUCTION}}. Its own placeholder {{SUGGESTION_VALUES}} is filled from the same constant the response schema uses, so the prompt can never name a value the schema rejects.';
$string['settingvalidationpromptwording'] = 'Language and wording check';
$string['settingvalidationpromptwording_desc'] = 'Replaces {{WORDING_INSTRUCTION}} in the validator prompt. Asks the validator to check that the question reads as correct, natural writing in the source text\'s language, to flag a question that contains its own answer, and to flag stems or options that name the source document with a meta-reference ("szöveg szerint", "according to the text"). Nothing in the validator\'s original three criteria covered these.';
$string['settingvalidatorcontextwindow'] = 'Validator context window (tokens)';
$string['settingvalidatorcontextwindow_desc'] = 'The validator model\'s context window, in tokens. The plugin fills at most 80% of it and counts the full source text into every round, so the questions are validated in as many rounds as that allows. Set it below the model\'s real limit and you get more, shorter rounds; set it above and the provider may reject the request.';
$string['settingvalidatorprompttemplate'] = 'Validator prompt template';
$string['settingvalidatorprompttemplate_desc'] = 'The complete system instruction sent to Gemini. Placeholders: {{SUGGESTION_INSTRUCTION}}, {{CATEGORY_INSTRUCTION}}, {{LANGUAGE_INSTRUCTION}} - the three fields below. The questions and the source text are sent as a separate user message. <strong>Deleting a placeholder means that instruction never reaches the model.</strong>';
$string['settingvalidatortokenbudget'] = 'Validator monthly token budget';
$string['settingvalidatortokenbudget_desc'] = '0 = unlimited. New generations are blocked once this many Gemini tokens have been used this cycle.';
$string['sourcefile'] = 'Or upload a file';
$string['sourcefile_help'] = 'Upload a PDF, DOCX or TXT file; its text will be extracted and added to the box below, where you can still edit it. Note: scanned or image-only PDFs (with no real, selectable text layer) cannot be extracted - only PDFs containing actual text will work.

The whole text of the document body goes into the box below - including anything the document originally hid or set in very small type. Headers, footers, comments and footnotes are deliberately left out: they are common places for content that is not part of the material itself. If you want any of that text, paste it into the box below.

What the plugin leaves out is a matter of structure rather than appearance: embedded code, embedded files and field instructions do not go in, because they are not prose somebody wrote. Everything else will be in the box below, where you can read and edit it before anything is submitted.';
$string['sourcefilemaxsize'] = 'Maximum file size: {$a}';
$string['sourcesectionheading'] = 'Source text';
$string['sourcetext'] = 'Source text';
$string['sourcetext_help'] = 'Paste or write the source material the AI should base the generated questions on.';
$string['sritemcountoverride'] = 'Ordering (SR) item count override (0 = use site default)';
$string['sritemcountoverride_help'] = 'Leave this at 0 to use the site default.

Ordering questions are sensitive to this number. Each one needs this many distinct items that your source text genuinely places in a sequence - a process, a chronology, a ranking or a list. The generator will not pad a list to reach the number, so if the text contains few such sequences it returns fewer ordering questions than you asked for.

If you get fewer ordering questions than expected, lowering this number or uploading a longer text usually returns more.';
